//funcion para hacer la validacion de el tamaño de la clave y el protocolo de seguridad de la misma , se valida el campo new password
function valida_clave(clave, id_usuario) {
  let msg_error = "";
  let clave_length = 8;
  if (clave.length > 0) {
    //si el campo no esta vacío
    if (clave.length >= clave_length) {
      //se valida que la clave cumpla con la cantidad de caracteres establecido
      var mayuscula = false;
      var minuscula = false;
      var numero = false;
      var caracter_raro = false;

      for (var i = 0; i < clave.length; i++) {
        //es para recorrer la clave escrita por el usuario
        if (clave.charCodeAt(i) >= 65 && clave.charCodeAt(i) <= 90) {
          mayuscula = true;
        } else if (clave.charCodeAt(i) >= 97 && clave.charCodeAt(i) <= 122) {
          minuscula = true;
        } else if (clave.charCodeAt(i) >= 48 && clave.charCodeAt(i) <= 57) {
          numero = true;
        } else {
          caracter_raro = true;
        }
      } //cierre del for
      if (!mayuscula || !minuscula || !caracter_raro || !numero) {
        msg_error += `<p>La contraseña debe contener por lo menos 1 mayúsculas, 1 número y 1 caracter especial para se válido.</p>`;
      } else {
        // Se verifica que la contraseña no se encuentre repetida
        var params = {
          action: "buscar_clave_bd",
          id_usuario: id_usuario,
          clave: clave,
        };
        $.ajaxSetup({async: false});
        $.ajax({
          url: $("#id_url_ajax").val() + "libs/usuarios_ajax.php",
          type: "POST",
          data: params,
          cache: false,
          dataType: "json",
          beforeSend: function (jqXHR, settings) {
            funct_msg_loading(".nexos-messages");
          },
          error: function (jqXHR, textStatus, errorThrown) {
            $(".nexos-messages").empty();
            msg_error += "<p>" + jqXHR.responseText + "</p>";
            console.log(jqXHR);
            console.log(textStatus);
            console.log(errorThrown);
          },
          success: function (data, textStatus, jqXHR) {
            $(".nexos-messages").empty();
            // console.log(data);
            if (data.result > 0) {
              msg_error += `<p>La contraseña ingresada ya había sido registrada anteriormente, por favor ingrese una contraseña diferente.</p>`;
            }
          },
        });
        $.ajaxSetup({async: true});
      }
    } else {
      msg_error += `<p>La contraseña debe tener mínimo ${clave_length} caracteres.</p>`;
    }
  }
  return msg_error;
}

function claves_iguales(new_pass, confirm_pass) {
  let msg_error = "";
  if (new_pass && confirm_pass) {
    if (new_pass != confirm_pass) {
      msg_error += `Las claves de digitadas no coinciden por favor verifiquelas.`;
    }
  }
  return msg_error;
}

function validaciones(tipo, campo, nombre) {
  if (tipo == "vacio") {
    if (campo == null || campo.length == 0) {
      //mostrarError("El campo " + nombre + " no puede estar vacío", msErrorUser);
      return "El campo " + nombre + " no puede estar vacío";
    } else {
      return true;
    }
  }

  if (tipo == "alfanumericos") {
    var exp_alfanume = /^[0-9a-zA-Z]+$/;
    if (!exp_alfanume.test(campo.trim())) {
      return "El campo " + nombre + " debe contener solo letras y números";
      //mostrarError("El campo " + nombre + " debe contener solo letras y números", msErrorUser);
    } else {
      return true;
    }
  }

  if (tipo == "password") {
    var carac_pass = /^[\s\S]{6,30}$/;
    if (!carac_pass.test(campo.trim())) {
      return "El campo " + nombre + " debe contener mínimo 6 dígitos y máximo 30";
      //mostrarError("El campo " + nombre + " debe contener mínimo 6 dígitos y máximo 30", msErrorPass);
    }

    var exp_pass = /^(?=.*[A-Za-z])(?=.*\d)([A-Za-z\d]|[^ ])/;
    if (!exp_pass.test(campo.trim())) {
      return "El campo " + nombre + " debe contener al menos 1 letra y 1 número";
      //mostrarError("El campo " + nombre + " debe contener al menos 1 letra y 1 número", msErrorPass);
    } else {
      return true;
    }
  }

  if (tipo == "email") {
    var exp_email = /[\w-\.]{2,}@([\w-]{2,}\.)*([\w-]{2,}\.)[\w-]{2,4}/;
    if (!exp_email.test(campo.trim())) {
      return "El campo " + nombre + " debe ser un correo electrónico valido";
    } else {
      return true;
    }
  }
}

function removerClaseserror(label, campo) {
  $(label).text("");
  $(campo).removeClass("errorClass");
  $(".error_user_log").css("display", "none");
  $(".error_pass").css("display", "none");
  // $(".error-text").css("display", "none");
}

function agregarClaseserror(label, campo, texto) {
  $(label).text(texto).css("color", "red");
  $(campo).addClass("errorClass");
  $(".error_user_log").css("display", "block");
  $(".error_pass").css("display", "block");
  // $(".error-text").css("display", "block");
}

function validarkeypress(label, campo) {
  if ($(label).val().length < 1) {
    removerClaseserror(label, campo);
  }
}

function comparacion(label, valor1, valor2, texto, campo) {
  if (valor1 != valor2) {
    agregarClaseserror(label, campo, texto);
    return false;
  } else {
    return true;
  }
}

function sincrono(Opcion, dato, campo, url, my_callback) {
  console.log(url);
  var resp = true;
  $.ajax({
    type: "POST", //TIPO DE PETICION PUEDE SER GET
    dataType: "json", //EL TIPO DE DATO QUE DEVUELVE PUEDE SER JSON/TEXT/HTML/XML
    url: url, //DIRECCION DONDE SE ENCUENTRA LA OPERACION A REALIZAR
    data: {Op: Opcion, campo: $(campo).val(), dato: dato}, //DATOS ENVIADOS PUEDE SER TEXT A TRAVEZ DE LA URL O PUEDE SER UN OBJETO
    beforeSend: function () {
      //ACCION QUE SUCEDE ANTES DE HACER EL SUBMIT
    },
    success: function (response) {
      //ACCION QUE SUCEDE DESPUES DE REALIZAR CORRECTAMENTE LA PETCION EL CUAL NOS TRAE UNA RESPUESTA
      if (response.respuesta == "GOOD") {
        //MANDAMOS EL MENSAJE QUE NOS DEVUELVE EL RESPONSE
        resp = true;
      } else {
        resp = false;
      }
      my_callback(resp);
    },
    error: function (jqXHR, textStatus, errorThrown) {
      console.log(jqXHR);
      console.log(textStatus);
      console.log(errorThrown);
      // alert('El servicio no esta disponible intentelo mas tarde. ' + jqXHR.responseText);
    },
  });
  return resp;
}

function showMessage(container, message, type, autoHide) {
  var color = "";
  switch (type) {
    case "message":
      color = "GREEN";
      break;

    case "warning":
      color = "ORANGE";
      break;

    case "error":
      color = "RED";
      break;
  }
  $("#" + container).css("color", color);
  $("#" + container).css("display", "block");
  $("#" + container).html(message);
  if (autoHide > 0) {
    setTimeout("hideMessage('" + container + "')", autoHide);
  }
}

function hideMessage(container) {
  $("#" + container).css("display", "none");
  $("#" + container).html("");
}

function showProcessingDialog(text) {
  if (text == null || text == "") {
    text = "Procesando, por favor espere . . .";
  }
  text = "<br>" + text + "<br><br>";
  $("#divProcessMessage").html(text);
  $("#divProcessing").dialog({
    modal: true,
    width: "auto",
    maxWidth: 300,
    height: "auto",
    title: document.title,
    closeOnEscape: false,
    open: function (event, ui) {
      $(".ui-dialog-titlebar-close", ui.dialog | ui).hide();
      $(".ui-dialog-titlebar").hide();
    },
  });
}

function hideProccessingDialog() {
  $("#divProcessing").dialog("close");
}

function minutesToString(minutes) {
  var numdays = Math.floor(minutes / 1440);
  var numhours = Math.floor((minutes % 1440) / 60);
  var numminutes = Math.floor(((minutes % 1440) % 60) % 60);
  textominutos = "";
  textodias = "";
  textohoras = "";
  if (numminutes == 1) {
    textominutos = numminutes + " minuto";
  } else if (numminutes > 1) {
    textominutos = numminutes + " minutos";
  }
  if (numhours == 1) {
    textohoras = numhours + " hora";
  } else if (numhours > 1) {
    textohoras = numhours + " horas";
  }

  if (numdays == 1) {
    textodias = numdays + " dia";
  } else if (numdays > 1) {
    textodias = numdays + " dias";
  }
  if (numdays > 0 && numhours > 0 && numminutes > 0) {
    return textodias + ", " + textohoras + " y " + textominutos;
  } else if (numdays > 0 && numhours == 0 && numminutes > 0) {
    return textodias + " y " + textominutos;
  } else if (numdays > 0 && numhours > 0 && numminutes == 0) {
    return textodias + " y " + textohoras;
  } else if (numdays == 0 && numhours > 0 && numminutes > 0) {
    return textohoras + " y " + textominutos;
  } else if (numdays > 0 && numhours == 0 && numminutes == 0) {
    return textodias;
  } else if (numdays == 0 && numhours > 0 && numminutes == 0) {
    return textohoras;
  } else if (numdays == 0 && numhours == 0 && numminutes > 0) {
    return textominutos;
  }
}

function calculaMinutos(tiempo, unidad_tiempo) {
  var minutos = "";
  if (tiempo && unidad_tiempo) {
    switch (unidad_tiempo) {
      case "1":
        // console.log("Entro en minutos");
        minutos = tiempo;
        break;

      case "2":
        // console.log("Entro en horas");
        minutos = tiempo * 60;
        break;

      case "3":
        // console.log("Entro en dias");
        minutos = tiempo * (60 * 24);
        break;

      case "4":
        // console.log("Entro en meses");
        minutos = tiempo * (60 * 24 * 30);
        break;
    }
  } else {
    minutos = "No se puede";
  }
  return minutos;
}

function validaFormatoArchivo(formatos, extension_archivo) {
  // console.log("Entro en función de validación de formato de archivo");
  var flag_formatos = 0;
  if (formatos && extension_archivo) {
    var extension = formatos.split(",");
    for (var i = 0; i < extension.length; i++) {
      if (extension_archivo == extension[i]) {
        flag_formatos = 1;
        break;
      }
    }
  }
  return flag_formatos;
}

function calcularDigitoVerificacion(myNit) {
  var vpri, x, y, z;

  // Se limpia el Nit
  myNit = myNit.replace(/\s/g, ""); // Espacios
  myNit = myNit.replace(/,/g, ""); // Comas
  myNit = myNit.replace(/\./g, ""); // Puntos
  myNit = myNit.replace(/-/g, ""); // Guiones

  // Se valida el nit
  if (isNaN(myNit)) {
    return "";
  }

  // Procedimiento
  vpri = new Array(16);
  z = myNit.length;

  vpri[1] = 3;
  vpri[2] = 7;
  vpri[3] = 13;
  vpri[4] = 17;
  vpri[5] = 19;
  vpri[6] = 23;
  vpri[7] = 29;
  vpri[8] = 37;
  vpri[9] = 41;
  vpri[10] = 43;
  vpri[11] = 47;
  vpri[12] = 53;
  vpri[13] = 59;
  vpri[14] = 67;
  vpri[15] = 71;

  x = 0;
  y = 0;
  for (var i = 0; i < z; i++) {
    y = myNit.substr(i, 1);
    // console.log ( y + "x" + vpri[z-i] + ":" ) ;

    x += y * vpri[z - i];
    // console.log ( x ) ;
  }

  y = x % 11;
  // console.log ( y ) ;

  return y > 1 ? 11 - y : y;
}

// FUNCION PARA VERIFICAR QUE UNA FECHA INGRESADA NO SEA MENOR A LA FECHA ACTUAL
function validaFechaActual(fecha) {
  var result = true;
  var f = new Date();
  var array_fecha = fecha.split("/");

  if (parseInt(array_fecha[2]) < f.getFullYear()) {
    result = false;
  }

  if (result) {
    if (parseInt(array_fecha[2]) == f.getFullYear() && parseInt(array_fecha[1]) < f.getMonth() + 1) {
      result = false;
    }
  }

  if (result) {
    if (parseInt(array_fecha[2]) == f.getFullYear() && parseInt(array_fecha[1]) == f.getMonth() + 1 && parseInt(array_fecha[0]) <= f.getDate()) {
      result = false;
    }
  }
  return result;
}

// FUNCIÓN PARA LLENAR AUTOMÁTICAMENTE EL NOMBRE DE UNA PERSONA O EMPRESA EN LOS MÓDULOS PROVEEDORES Y REMITENTES/DESTINATARIOS
function llenaNombreProveedor(nombre, rndc_nombre, primer_apellido, segundo_apellido) {
  $("#" + nombre).val("");
  var return_nombre =
    $("#" + rndc_nombre)
      .val()
      .trim() +
    " " +
    $("#" + primer_apellido)
      .val()
      .trim() +
    " " +
    $("#" + segundo_apellido)
      .val()
      .trim();
  $("#" + nombre).val(return_nombre);
}

// FUNCIÓN PARA AGREGAR SEPARADOR DE MILES A NÚMEROS EN LA DIGITACIÓN DE NÚMEROS EN LOS CAMPOS
function getSeparadorMiles(input) {
  var num = input.value.replace(/\./g, "");
  if (!isNaN(num)) {
    num = num
      .toString()
      .split("")
      .reverse()
      .join("")
      .replace(/(?=\d*\.?)(\d{3})/g, "$1.");
    num = num.split("").reverse().join("").replace(/^[\.]/, "");
    input.value = num;
  } else {
    input.value = input.value.replace(/[^\d\.]*/g, "");
  }
}

// FUNCIÓN PARA AGREGAR SEPARADOR DE MILES A NÚMEROS EN LA DIGITACIÓN DE NÚMEROS EN LOS CAMPOS
function getSeparadorMiles_1(num) {
  num = num
    .toString()
    .split("")
    .reverse()
    .join("")
    .replace(/(?=\d*\.?)(\d{3})/g, "$1.");
  num = num.split("").reverse().join("").replace(/^[\.]/, "");
  return num;
}

function getFormatoNumeroDecimal(input) {
  var num = input.value.replace(/\./g, "").replace(/\,/g, "");

  if (!isNaN(num)) {
    num = num
      .replace(/\D/g, "")
      .replace(/([0-9])([0-9]{2})$/, "$1,$2")
      .replace(/\B(?=(\d{3})+(?!\d)\.?)/g, ".");
    input.value = num;
  } else {
    input.value = input.value.replace(/[^\d\.]*/g, "");
  }
}

function getFormatoNumeroDecimal_value(value) {
  var num = String(value).replace(/\./g, "").replace(/\,/g, "");
  if (!isNaN(num)) {
    num = num
      .replace(/\D/g, "")
      .replace(/([0-9])([0-9]{2})$/, "$1,$2")
      .replace(/\B(?=(\d{3})+(?!\d)\.?)/g, ".");
  } else {
    num = value.replace(/[^\d\.]*/g, "");
  }
  return num;
}

/***** FUNCIONES PARA CREAR GRÁFICAS *****/
//Line Chart
function line_chart(params) {
  new Morris.Line({
    element: params.id,
    data: params.data,
    xkey: params.xkey,
    ykeys: params.ykeys,
    labels: params.labels,
    lineColors: params.lineColors,
    hideHover: "auto",
  });
}

//Area chart
function area_chart(params) {
  new Morris.Area({
    element: params.id,
    data: params.data,
    xkey: params.xkey,
    ykeys: params.ykeys,
    labels: params.labels,
    lineColors: params.lineColors,
    pointSize: 2,
    hideHover: "auto",
  });
}

//Bar chart
function bar_chart(params) {
  new Morris.Bar({
    element: params.id,
    data: params.data,
    xkey: params.xkey,
    ykeys: params.ykeys,
    labels: params.labels,
    barColors: params.barColors,
    barRatio: 0.4,
    xLabelAngle: 35,
    hideHover: "auto",
  });
}

